'use client';

import * as React from 'react';
import {createComponent} from '@lit/react';
import '@material/web/labs/gb/components/loadingindicator/md-gb-loading-indicator.js';
import {LoadingIndicatorElement} from '@material/web/labs/gb/components/loadingindicator/loading-indicator-element.js';

/**
 * A Material Design component. Wraps <md-gb-loading-indicator>.
 * Docs: https://material-web.dev/3.0/components/loading-indicator/
 */
export const MdLoadingIndicator = createComponent({
  react: React,
  tagName: 'md-gb-loading-indicator',
  elementClass: LoadingIndicatorElement,
});

export type MdLoadingIndicatorProps = React.ComponentProps<typeof MdLoadingIndicator>;
